import React, { useContext, useEffect, useState } from 'react';
import { ConfigProvider, Popover, Space } from '@arco-design/web-react';
import {
  IconCheckCircleFill,
  IconCloseCircleFill,
  IconExclamationCircleFill,
  IconLoading,
} from '@arco-design/web-react/icon';
import cls from 'classnames';
import FormItemLabel from './FormLabel';
import { CSSTransition } from 'react-transition-group';
import { connect, mapProps } from '@formily/react';
import { isVoidField } from '@formily/core';
import { IFormItemProps } from './interface';
import { useFormLayout } from '../FormLayout';
import { pickDataProps, usePrefixCls } from '../__builtins__';

export const VALIDATE_STATUS = {
  error: 'error',
  success: 'success',
  warning: 'warning',
  validating: 'validating',
};

const ICON_MAP = {
  [VALIDATE_STATUS.error]: <IconCloseCircleFill />,
  [VALIDATE_STATUS.warning]: <IconExclamationCircleFill />,
  [VALIDATE_STATUS.success]: <IconCheckCircleFill />,
  [VALIDATE_STATUS.validating]: <IconLoading />,
};

const useFormItemLayout = (props: IFormItemProps): IFormItemProps => {
  const layout = useFormLayout();
  const layoutType = props.layout ?? layout.layout ?? 'horizontal';
  return {
    ...props,
    layout: layoutType,
    requiredSymbol: 'requiredSymbol' in props ? props.requiredSymbol : layout.requiredSymbol,
    colon: props.colon ?? layout.colon,
    labelAlign:
      layoutType === 'vertical' ? props.labelAlign ?? 'left' : props.labelAlign ?? layout.labelAlign ?? 'right',
    labelWrap: props.labelWrap ?? layout.labelWrap,
    labelWidth: 'labelWidth' in props ? props.labelWidth : layout.labelWidth,
    wrapperWidth: 'wrapperWidth' in props ? props.wrapperWidth : layout.wrapperWidth,
    labelCol: 'labelCol' in props ? props.labelCol : layout.labelCol,
    wrapperCol: 'wrapperCol' in props ? props.wrapperCol : layout.wrapperCol,
    size: props.size ?? layout.size,
    required: props.required,
    requiredAlign: 'requiredAlign' in props ? props.requiredAlign : layout.requiredAlign,
    tooltip: props.tooltip ?? layout.tooltip,
    controlChildStyle: props.controlChildStyle,
  };
};

export const BaseItem: React.FC<React.PropsWithChildren<IFormItemProps>> = ({ children, ...props }) => {
  const formLayout = useFormItemLayout(props);
  const {
    className,
    style,
    label,
    help,
    helpLayout = 'normal',
    size,
    colon,
    required,
    labelWrap,
    addonBefore,
    addonAfter,
    getPopupContainer,
    validateStatus,
    hasFeedback,
    extra,
    layout,
    requiredSymbol,
    labelCol,
    wrapperCol,
    labelAlign,
    labelWidth,
    wrapperWidth,
    requiredAlign,
    controlChildStyle,
    controlPopover,
    validateInfo,
    hasInnerFormItem = false,
    wrapperedComponentValue,
    tooltip
  } = formLayout;
  const prefixCls = usePrefixCls('formily-item');
  const ctx = useContext(ConfigProvider.ConfigContext);
  const labelStyle = { ...formLayout.labelStyle };
  const wrapperStyle = { ...formLayout.wrapperStyle };

  if (labelWidth || labelWidth === 0) {
    labelStyle.width = labelWidth;
    labelStyle.maxWidth = labelWidth;
  }
  if (wrapperWidth || wrapperWidth === 0) {
    wrapperStyle.width = wrapperWidth;
    wrapperStyle.maxWidth = wrapperWidth;
  }

  // 栅格模式
  let enableCol = false;
  if (!labelStyle.width && !wrapperStyle.width && layout === 'horizontal') {
    enableCol = true;
  }

  const renderLabel = () => {
    return (
      <FormItemLabel
        enableCol={enableCol}
        label={label}
        showColon={colon as boolean}
        tooltip={tooltip}
        required={required}
        labelAlign={labelAlign}
        requiredSymbol={requiredSymbol}
        requiredAlign={requiredAlign}
        labelCol={labelCol}
        labelStyle={labelStyle}
        labelWrap={labelWrap}
        layout={layout}
      />
    );
  };


  const [popoverErrorVisible, setPopoverErrorVisible] = useState(false);
  useEffect(() => {
    if (!help) setPopoverErrorVisible(false);
  }, [help])

  const formatChildren = () => {
    if (controlPopover && (controlPopover.helperTips || controlPopover.content)) {
      const { helperTips, ...popoverProps } = controlPopover;
      return (
        <Popover
          getPopupContainer={getPopupContainer}
          disabled={!helperTips && !popoverProps?.content}
          content={
            <div>
              {helperTips?.map((item, index) => {
                const isError = validateInfo?.errors && validateInfo?.errors?.findIndex?.(error => error === item) > -1;
                return (
                  <div key={index} className={`${prefixCls}-helper-tips`}>
                    <Space size={4} align="start">
                      <span
                        className={cls(`${prefixCls}-helper-tips-icon`, {
                          [`${prefixCls}-helper-tips-icon-error`]: isError,
                          [`${prefixCls}-helper-tips-icon-success`]: !isError && !!wrapperedComponentValue,
                        })}
                      >
                        {ICON_MAP[isError ? VALIDATE_STATUS.error : VALIDATE_STATUS.success]}
                      </span>
                      <span className={`${prefixCls}-helper-tips-text`}>{item}</span>
                    </Space>
                  </div>
                );
              })}
            </div>
          }
          {...popoverProps}
        >
          {children}
        </Popover>
      );
    } else if (formLayout.helpLayout === 'popover') {
      return (
        <Popover
          disabled={!help}
          popupVisible={popoverErrorVisible}
          getPopupContainer={getPopupContainer}
          content={
            <div
              className={cls({
                [`${prefixCls}-message-status-${validateStatus}`]: Boolean(validateStatus),
              })}
            >
              <div
                className={cls(`${prefixCls}-message`, {
                  [`${prefixCls}-message-help`]: true,
                })}
              >
                <Space size={4}>
                  {validateStatus && (
                    <span className={`${prefixCls}-feedback`} style={{ position: 'relative', right: 0 }}>
                      {ICON_MAP[validateStatus]}
                    </span>
                  )}
                  {help}
                </Space>
              </div>
            </div>
          }
          onVisibleChange={setPopoverErrorVisible}
          {...controlPopover}
        >
          {children}
        </Popover>
      );
    }

    return children;
  };

  const Content = <div
    {...pickDataProps(props)}
    style={style}
    id={props.id}
    className={cls(className, {
      [`${prefixCls}`]: true,
      [`${prefixCls}-layout-${layout}`]: true,
      [`${prefixCls}-size-${size}`]: Boolean(size),
      [`${prefixCls}-no-bottom`]: helpLayout === 'normal' && (help || validateStatus === VALIDATE_STATUS.error),
      [`${prefixCls}-status-${validateStatus}`]: !hasInnerFormItem && Boolean(validateStatus),
      [`${prefixCls}-message-status-${validateStatus}`]: Boolean(validateStatus),
      [`${prefixCls}-has-feedback`]: validateStatus && hasFeedback,
      [`${prefixCls}-status`]: Boolean(validateStatus),
    })}
    data-grid-span={formLayout.gridSpan}
  >
    {renderLabel()}
    <div
      className={cls({
        [`${prefixCls}-control`]: true,
        [`${prefixCls}-col-${wrapperCol}`]: enableCol && Boolean(wrapperCol) && label,
      })}
      style={wrapperStyle}
    >
      <div className={cls(`${prefixCls}-control-content`)}>
        {addonBefore && <div className={cls(`${prefixCls}-addon-before`)}>{addonBefore}</div>}
        <div
          className={cls(`${prefixCls}-control-children`)}
          style={controlChildStyle}
        >
          {formatChildren()}
          {validateStatus && hasFeedback && (
            <div className={`${prefixCls}-feedback`}>{ICON_MAP[validateStatus]}</div>
          )}
        </div>
        {addonAfter && <div className={cls(`${prefixCls}-addon-after`)}>{addonAfter}</div>}
      </div>
      {Boolean(help) && helpLayout !== 'popover' && (
        <CSSTransition in={Boolean(help)} appear classNames="formblink" timeout={300} unmountOnExit>
          <div
            className={cls(`${prefixCls}-message`, {
              [`${prefixCls}-message-help`]: Boolean(help),
            })}
          >
            {help}
          </div>
        </CSSTransition>
      )}
      {extra && <div className={`${prefixCls}-extra`}>{extra}</div>}
    </div>
  </div>

  if (hasInnerFormItem) {
    return Content;
  }
  return (<ConfigProvider {...ctx} size={size}>
    {Content}
  </ConfigProvider>)
};

type ComposeFormItem = React.FC<React.PropsWithChildren<IFormItemProps>> & {
  BaseItem?: React.FC<React.PropsWithChildren<IFormItemProps>>;
};

export const FormItem: ComposeFormItem = connect(
  BaseItem,
  mapProps((props, field) => {
    if (!field) {
      return props;
    }
    if (isVoidField(field)) {
      return {
        label: field.title || props.label,
        required: props.required,
        extra: props.extra || field.description,
      };
    }

    const takeValidateStatus = () => {
      if (field.validating) {
        return 'validating';
      }
      return field.decoratorProps.validateStatus || field.validateStatus;
    };

    const takeRequired = () => {
      if (field.required && field.pattern !== 'readPretty') {
        return true;
      }
      if ('required' in props) {
        return props.required;
      }
      return false;
    };

    const takeMessage = () => {
      const firstMessage = (messages: any[]) => {
        const [first] = messages.filter(Boolean) || []
        return first;
      }
      if (field.validating) {
        return;
      }
      if (props.help) {
        return props.help;
      }
      if (field.selfErrors.length) {
        return firstMessage(field.selfErrors);
      }
      if (field.selfWarnings.length) {
        return firstMessage(field.selfWarnings);
      }
      if (field.selfSuccesses.length) {
        return firstMessage(field.selfSuccesses);
      }
    };

    return {
      label: props.label || field.title,
      help: props.help || takeMessage(),
      extra: props.extra || field.description,
      validateStatus: takeValidateStatus(),
      required: takeRequired(),
      validateInfo: props.validateInfo || {
        errors: field.selfErrors
      },
      wrapperedComponentValue: field.value,
    };
  }),
);

FormItem.BaseItem = BaseItem;

FormItem.displayName = 'FormItem';

export default FormItem;
